frontend.rutas:
import { Routes } from '@angular/router';
import { authGuard } from './core/guardias/auth.guard';

export const routes: Routes = [
    {
        path: 'autenticacion',
        loadComponent: () => import('./auth/autenticacion/autenticacion').then(m => m.Autenticacion)
    },
    {
        path: 'verificar-correo/:token',
        loadComponent: () => import('./auth/verificar-correo/verificar-correo').then(m => m.VerificarCorreo)
    },
    {
        path: '',
        canActivate: [authGuard],
        loadComponent: () => import('./principales/layout-principal/layout-principal').then(m => m.LayoutPrincipal),
        children: [
            { path: '', redirectTo: 'dashboard', pathMatch: 'full' },
            {
                path: 'dashboard',
                loadComponent: () => import('./principales/dashboard/dashboard').then(m => m.Dashboard)
            },
            {
                path: 'habitos',
                loadComponent: () => import('./principales/habitos/habitos').then(m => m.Habitos)
            },
            {
                path: 'ideas',
                loadComponent: () => import('./principales/notas/notas').then(m => m.Notas)
            },
            {
                path: 'notas',
                redirectTo: 'ideas',
                pathMatch: 'full'
            },
            {
                path: 'calendario',
                loadComponent: () => import('./principales/eventos/eventos').then(m => m.Eventos)
            },
            {
                path: 'eventos',
                redirectTo: 'calendario',
                pathMatch: 'full'
            },
            {
                path: 'estadisticas',
                loadComponent: () => import('./principales/redireccion-tab/redireccion-tab').then(m => m.RedireccionTab)
            },
            {
                path: 'finanzas',
                loadComponent: () => import('./principales/finanzas/finanzas').then(m => m.Finanzas)
            },
            {
                path: 'entrenamiento',
                loadComponent: () => import('./principales/gimnasio/gimnasio').then(m => m.Gimnasio)
            },
            {
                path: 'gimnasio',
                redirectTo: 'entrenamiento',
                pathMatch: 'full'
            },
            {
                path: 'rutinas',
                loadComponent: () => import('./principales/rutinas/rutinas').then(m => m.Rutinas)
            },
            {
                path: 'perfil',
                loadComponent: () => import('./principales/perfil/perfil').then(m => m.Perfil)
            }
        ]
    },
    {
        path: '**',
        loadComponent: () => import('./principales/no-encontrado/no-encontrado').then(m => m.NoEncontrado)
    }
];
